'use client';

import { useEffect, useRef, useState } from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './trend-line-morph.css';

export interface TrendLineMorphProps {
  /** Same length as `labels`. Changing it morphs the line. */
  values: number[];
  labels: string[];
  /** Fixed axis range, so both series share one scale. */
  min: number;
  max: number;
  unit?: string;
  /** Index of the point to read out. */
  selected: number;
  onSelect: (index: number) => void;
  label: string;
  className?: string;
}

const W = 300;
const H = 150;
const PAD = 24;

/**
 * Morphs a line between series on fixed axes. A row of buttons picks a
 * point and shows its exact value, so nothing depends on hovering.
 */
export function TrendLineMorph({
  values,
  labels,
  min,
  max,
  unit = '',
  selected,
  onSelect,
  label,
  className = '',
}: TrendLineMorphProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = useState(values);
  const current = useRef(values);

  useEffect(() => {
    const from = current.current;
    if (reduced || from.length !== values.length) {
      current.current = values;
      setShown(values);
      return;
    }
    let frame = 0;
    const start = performance.now();
    const tick = (now: number) => {
      const k = Math.min(1, (now - start) / 600);
      const ease = 1 - Math.pow(1 - k, 3);
      const next = values.map((v, i) => from[i] + (v - from[i]) * ease);
      current.current = next;
      setShown(next);
      if (k < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [values, reduced]);

  const x = (i: number) => PAD + (i * (W - PAD * 2)) / (values.length - 1);
  const y = (v: number) => H - PAD - ((v - min) / (max - min)) * (H - PAD * 2);
  const d = shown
    .map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)} ${y(v).toFixed(1)}`)
    .join(' ');
  const ticks = [min, (min + max) / 2, max];

  return (
    <div className={`mg-trend ${className}`}>
      <svg viewBox={`0 0 ${W} ${H}`} role='img' aria-label={label}>
        {ticks.map((t) => (
          <g key={t}>
            <line
              className='mg-trend__grid'
              x1={PAD}
              x2={W - PAD}
              y1={y(t)}
              y2={y(t)}
            />
            <text
              className='mg-trend__axis'
              x={PAD - 4}
              y={y(t) + 4}
              textAnchor='end'
            >
              {t}
            </text>
          </g>
        ))}
        <path className='mg-trend__line' d={d} />
        {shown.map((v, i) => (
          <circle
            key={i}
            className='mg-trend__point'
            data-selected={i === selected}
            cx={x(i)}
            cy={y(v)}
            r={i === selected ? 6 : 3.5}
          />
        ))}
      </svg>
      <div className='mg-trend__picker' role='group' aria-label='Read a point'>
        {labels.map((l, i) => (
          <button
            key={l}
            type='button'
            aria-pressed={i === selected}
            onClick={() => onSelect(i)}
          >
            {l}
          </button>
        ))}
      </div>
      <p className='mg-trend__readout' aria-live='polite'>
        {labels[selected]}:{' '}
        <strong>
          {values[selected]}
          {unit}
        </strong>
      </p>
    </div>
  );
}

.mg-trend {
  display: grid;
  gap: 8px;
  color: var(--mg-ink, #0c1738);
}

.mg-trend svg {
  display: block;
  width: 100%;
  height: auto;
}

.mg-trend__grid {
  stroke: #e1e8fb;
}

.mg-trend__axis {
  fill: #6b7699;
  font-size: 9px;
}

.mg-trend__line {
  fill: none;
  stroke: var(--mg-accent, #164cff);
  stroke-width: 3;
  stroke-linejoin: round;
}

.mg-trend__point {
  fill: #fff;
  stroke: var(--mg-accent, #164cff);
  stroke-width: 2;
}

.mg-trend__point[data-selected='true'] {
  fill: var(--mg-green, #b6ff3b);
  stroke: var(--mg-ink, #0c1738);
}

.mg-trend__picker {
  display: grid;
  grid-auto-flow: column;
  gap: 4px;
}

.mg-trend__picker button {
  min-height: 36px;
  border: 1px solid var(--mg-line-strong, #b9c5e6);
  border-radius: 6px;
  background: #fff;
  color: inherit;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.mg-trend__picker button[aria-pressed='true'] {
  border-color: var(--mg-ink, #0c1738);
  background: var(--mg-ink, #0c1738);
  color: #fff;
}

.mg-trend__picker button:focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: 1px;
}

.mg-trend__readout {
  margin: 0;
  color: #46527a;
  font-size: 13px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-trend__point {
    transition: none;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
